/**
 * 词典卡片的落点：不能压住被点的那个词，也不能跑出屏幕。
 *
 * 单独拎出来是因为它是一段纯几何：给「词的位置、卡片多大、视口多大」，
 * 算「卡片摆哪」。摆的次序是正下方 → 正上方 → 右侧 → 左侧，
 * 每一个都先收进视口再看会不会压着词，四个都不行（屏幕实在太小）
 * 才退到「尽量让词露出来」的折中位置。
 */

export interface LookupRect {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

export interface LookupSize {
  width: number;
  height: number;
}

export interface LookupPoint {
  left: number;
  top: number;
}

/** 卡片和词之间留的空档。 */
const GAP = 14;
/** 卡片离屏幕边的最小距离。 */
const MARGIN = 12;

function overlaps(left: number, top: number, size: LookupSize, anchor: LookupRect) {
  return (
    left < anchor.right &&
    left + size.width > anchor.left &&
    top < anchor.bottom &&
    top + size.height > anchor.top
  );
}

export function placeLookupCard(
  anchor: LookupRect,
  card: LookupSize,
  viewport: LookupSize,
): LookupPoint {
  const maxLeft = Math.max(MARGIN, viewport.width - card.width - MARGIN);
  const maxTop = Math.max(MARGIN, viewport.height - card.height - MARGIN);
  const clampX = (value: number) => Math.min(Math.max(value, MARGIN), maxLeft);
  const clampY = (value: number) => Math.min(Math.max(value, MARGIN), maxTop);

  const candidates: LookupPoint[] = [
    // 正下方：卡片左缘和词的左缘对齐，读起来最顺。
    { left: clampX(anchor.left), top: anchor.bottom + GAP },
    // 正上方：词在页面下半时走这条。
    { left: clampX(anchor.left), top: anchor.top - card.height - GAP },
    // 右侧、左侧：上下都没地方才走这两条。
    { left: anchor.right + GAP, top: clampY(anchor.top) },
    { left: anchor.left - card.width - GAP, top: clampY(anchor.top) },
  ];

  for (const candidate of candidates) {
    const left = clampX(candidate.left);
    const top = clampY(candidate.top);
    if (!overlaps(left, top, card, anchor)) return { left, top };
  }

  // 视口小到怎么摆都压着词：选压得最少的那条（通常是正下方）。
  let best = { left: clampX(anchor.left), top: clampY(anchor.bottom + GAP) };
  let bestArea = Number.POSITIVE_INFINITY;
  for (const candidate of candidates) {
    const left = clampX(candidate.left);
    const top = clampY(candidate.top);
    const overlapWidth = Math.min(left + card.width, anchor.right) - Math.max(left, anchor.left);
    const overlapHeight = Math.min(top + card.height, anchor.bottom) - Math.max(top, anchor.top);
    const area = Math.max(0, overlapWidth) * Math.max(0, overlapHeight);
    if (area < bestArea) {
      bestArea = area;
      best = { left, top };
    }
  }
  return best;
}

/** 卡片被拖动后收进视口：留一点边，别让手指够不着。 */
export function clampLookupPosition(
  point: LookupPoint,
  card: LookupSize,
  viewport: LookupSize,
  edge = 8,
): LookupPoint {
  const maxLeft = Math.max(edge, viewport.width - card.width - edge);
  const maxTop = Math.max(edge, viewport.height - card.height - edge);
  return {
    left: Math.min(Math.max(point.left, edge), maxLeft),
    top: Math.min(Math.max(point.top, edge), maxTop),
  };
}
