/**
 * 阅读时的三条沉淀路径，浮动工具条、词典卡片、AI 面板共用：
 *
 *   加入复习 → 单词本（复习，书架钢琴 Words 区）
 *   存知识卡 → 书架抽屉 · Collection
 *   加入语料 → 语料库（KWIC 检索页）
 *
 * 知识卡没有现成释义时补一次 AI 请求（失败退回本地兜底），其余动作都是即时的。
 */
import { useCallback } from "react";
import type { LanguageInsight } from "@leafia/shared";
import { fallbackInsight } from "../../data/demo";
import { api } from "../../lib/api";
import { addCollectedItem, buildKnowledgeCard } from "../../lib/collection";
import { useLeafia } from "../../store/leafia";
import { useVocabulary } from "../../store/vocabulary";

export interface ReaderSource {
  bookId: string;
  /** 卡片和语料的来源标注，例如「Linguistics」。 */
  bookLabel: string;
}

export interface KnowledgeCardRequest {
  term: string;
  contextBefore?: string;
  contextAfter?: string;
  /** 已经查过词典/AI 的话直接复用，省一次请求。 */
  insight?: LanguageInsight | null;
}

export function useReaderActions(source: ReaderSource) {
  const showToast = useLeafia((state) => state.showToast);
  const addToVocabulary = useVocabulary((state) => state.addInsight);

  const addToReview = useCallback(
    (insight: LanguageInsight, excerpt?: string) => {
      addToVocabulary(insight, source.bookLabel, excerpt);
      showToast(`已加入复习：${insight.term}`);
    },
    [addToVocabulary, showToast, source.bookLabel],
  );

  const saveKnowledgeCard = useCallback(
    async (request: KnowledgeCardRequest) => {
      const term = request.term.trim().replace(/\s+/g, " ").slice(0, 60);
      if (!term) return;
      let insight = request.insight ?? null;
      if (!insight) {
        showToast("正在整理知识卡…");
        try {
          const response = await api.insight({
            noteId: `book-${source.bookId}`,
            pageId: source.bookId,
            selectedText: term,
            contextBefore: request.contextBefore,
            contextAfter: request.contextAfter,
            locale: "zh-CN",
          });
          insight = response.insight;
        } catch {
          insight = fallbackInsight(term);
        }
      }
      const card = buildKnowledgeCard({
        term,
        concept: insight.meaningsZh.join("；") || insight.definitionEn,
        sourceLabel: source.bookLabel,
        sourceId: source.bookId,
      });
      const added = addCollectedItem(card);
      showToast(
        added
          ? `已存入书架抽屉 · Collection：${card.title}`
          : `这张知识卡已经在抽屉里了：${card.title}`,
      );
    },
    [showToast, source.bookId, source.bookLabel],
  );

  const addToCorpus = useCallback(
    async (insight: LanguageInsight) => {
      try {
        const response = await api.addCorpus({
          insight,
          sourceLabel: source.bookLabel,
          tags: ["reading", source.bookId],
        });
        useLeafia.setState((state) => ({
          corpus: [
            response.entry,
            ...state.corpus.filter((entry) => entry.id !== response.entry.id),
          ],
        }));
        showToast(`已收入语料：${response.entry.term}`);
      } catch {
        showToast("语料保存失败，请稍后重试。");
      }
    },
    [showToast, source.bookId, source.bookLabel],
  );

  return { addToReview, saveKnowledgeCard, addToCorpus };
}
